def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    visited = set()
    path_stack = [(start, [start])]

    while path_stack:
        current, path = path_stack.pop()
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            return path
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                path_stack.append((neighbor, path + [neighbor]))

    return None

# Example usage:
graph = {
    'A': ['B', 'C'],
    'B': ['D'],
    'C': ['E'],
    'D': ['F'],
    'E': ['F'],
    'F': []
}

print(find_path(graph, 'A', 'F'))  # Output: ['A', 'C', 'E', 'F']
print(find_path(graph, 'A', 'G'))  # Output: None
